    @Test void schedulerExpressionIncludesAllBeijingBusinessBoundaries()throws Exception{
        org.springframework.scheduling.annotation.Scheduled annotation=OpsJobs.class.getMethod("scheduled").getAnnotation(org.springframework.scheduling.annotation.Scheduled.class);
        ZoneId zone=ZoneId.of(annotation.zone());assertEquals(ZoneId.of("Asia/Shanghai"),zone);
        org.springframework.scheduling.support.CronExpression cron=org.springframework.scheduling.support.CronExpression.parse(annotation.cron());
        for(String time:Arrays.asList("2026-11-15T17:30:12","2026-11-15T18:00:12","2026-11-15T18:30:12","2026-12-01T00:05:12")){
            ZonedDateTime boundary=LocalDateTime.parse(time).atZone(zone);assertEquals(boundary,cron.next(boundary.minusSeconds(1)));
        }
    }
