    @Test void exportsContainChineseAndDoNotCreateExcelFormulas()throws Exception{at("2026-11-15T18:01:00");Map<String,Object> r=open(KEEPER,"keeper");OpsExport export=new OpsExport();List<List<String>> rows=export.rows(r);rows.add(Arrays.asList("测试内容","=HYPERLINK(\"test\")"));for(int i=0;i<80;i++)rows.add(Arrays.asList("长文本测试",String.join("",Collections.nCopies(5,"主理人明日跟进任务，核对支出与日报。"))));byte[] excel=export.excel(rows),pdf=export.pdf(rows);try(XSSFWorkbook book=new XSSFWorkbook(new ByteArrayInputStream(excel))){boolean found=false;for(org.apache.poi.ss.usermodel.Row row:book.getSheetAt(0)){for(org.apache.poi.ss.usermodel.Cell cell:row){assertEquals(CellType.STRING,cell.getCellType());if(cell.getStringCellValue().startsWith("=HYPERLINK"))found=true;}}assertTrue(found);}try(PDDocument doc=Loader.loadPDF(pdf)){assertTrue(doc.getNumberOfPages()>1);String text=new PDFTextStripper().getText(doc);assertTrue(text.contains("每日工作报告"));assertTrue(text.contains("今日平台营收"),"Chinese metric label must be searchable");}Path dir=Paths.get("artifacts/operations-reports-20261115");Files.write(dir.resolve("report-test.xlsx"),excel);Files.write(dir.resolve("report-test.pdf"),pdf);}
